import json, sys

after = json.load(sys.stdin)
# Save after
with open('after-cpm-packages.json', 'w') as f:
    json.dump(after, f, indent=2)

def extract(data):
    result = {}
    for proj in data['projects']:
        name = proj['path'].split('/')[-1]
        for fw in proj['frameworks']:
            for pkg in fw.get('topLevelPackages', []):
                result[(name, pkg['id'])] = pkg['resolvedVersion']
    return result

a = extract(after)
print('Post-conversion packages:')
for (proj, pkg), ver in sorted(a.items()):
    print(f'  {proj}: {pkg} {ver}')
"

